insert into public.exercises (name_pl, name_en, muscle_groups, primary_muscles, secondary_muscles, equipment, movement_pattern, level, description, mechanic, force, image_urls, image_url, source, external_id, attribution, created_by) values ('Wykroki chodzone z hantlami', 'Dumbbell Walking Lunge', array['quadriceps','glutes','hamstrings','adductors']::text[], array['quadriceps']::text[], array['glutes','hamstrings','adductors']::text[], array['dumbbell']::text[], 'lunge', 'beginner', 'Wykroki w marszu z hantlami w dłoniach. Kolano przedniej nogi nad stopą, tułów wyprostowany, odpychaj się z pięty.', 'compound', 'push', array['https://wger.de/media/exercise-images/113/Walking-lunges-1.png','https://wger.de/media/exercise-images/206/6ec66efd-e74f-4142-bed1-0a0ac74e3294.png','https://wger.de/media/exercise-images/113/Walking-lunges-2.png','https://wger.de/media/exercise-images/113/Walking-lunges-3.png','https://wger.de/media/exercise-images/113/Walking-lunges-4.png']::text[], 'https://wger.de/media/exercise-images/113/Walking-lunges-1.png', 'wger', 'dcc6e237-a8bb-4eca-bbc5-7fb852636f6a', 'wger.de, autor: wger.de, licencja CC-BY-SA 3', null) on conflict (source, external_id) do nothing;
insert into public.exercises (name_pl, name_en, muscle_groups, primary_muscles, secondary_muscles, equipment, movement_pattern, level, description, mechanic, force, image_urls, image_url, source, external_id, attribution, created_by) values ('Podciąganie na maszynie z odciążeniem', 'Machine Assisted Pull-Up', array['lats','biceps','middle back']::text[], array['lats']::text[], array['biceps','middle back']::text[], array['machine']::text[], 'pull_v', 'beginner', 'Podciąganie z kolanami na platformie maszyny, która odejmuje część masy ciała. Dobra regresja podciągania – zmniejszaj odciążenie z tygodnia na tydzień.', 'compound', 'pull', array[]::text[], null, 'wger', '7f834f07-fa7b-46b6-8ffa-45930b0602db', 'wger.de, autor: wger.de, licencja CC-BY-SA 3', null) on conflict (source, external_id) do nothing;
insert into public.exercises (name_pl, name_en, muscle_groups, primary_muscles, secondary_muscles, equipment, movement_pattern, level, description, mechanic, force, image_urls, image_url, source, external_id, attribution, created_by) values ('Skip A w miejscu (kolana wysoko)', 'High Knee Jumps', array['quadriceps','calves','abdominals']::text[], array['quadriceps']::text[], array['calves','abdominals']::text[], array['body only']::text[], 'cardio', 'beginner', 'Szybki bieg w miejscu z unoszeniem kolan do wysokości bioder. Lądowanie na śródstopiu, praca rąk jak w sprincie.', 'compound', 'push', array['https://wger.de/media/exercise-images/285/4141e8b2-d9f2-4597-8ef0-7768127fd0ec.png']::text[], 'https://wger.de/media/exercise-images/285/4141e8b2-d9f2-4597-8ef0-7768127fd0ec.png', 'wger', '3edbb63e-f326-4bd0-8af3-2d5deabb864f', 'wger.de, autor: nate303303, licencja CC-BY-SA 4', null) on conflict (source, external_id) do nothing;
insert into public.exercises (name_pl, name_en, muscle_groups, primary_muscles, secondary_muscles, equipment, movement_pattern, level, description, mechanic, force, image_urls, image_url, source, external_id, attribution, created_by) values ('Hollow body (łódka)', 'Hollow Hold', array['abdominals','quadriceps']::text[], array['abdominals']::text[], array['quadriceps']::text[], array['body only']::text[], 'core', 'beginner', 'Leżenie na plecach z uniesionymi barkami i nogami, lędźwie dociśnięte do podłogi. Podstawa gimnastyczna napięcia brzucha – skracaj dźwignię, gdy lędźwie odrywają się od podłoża.', 'isolation', 'static', array['https://wger.de/media/exercise-images/297/b10d3341-baa8-49ab-b462-5b3529389aac.png']::text[], 'https://wger.de/media/exercise-images/297/b10d3341-baa8-49ab-b462-5b3529389aac.png', 'wger', 'd059c63d-0a81-48a3-912a-44070c0def2e', 'wger.de, autor: Behrooz, licencja CC0', null) on conflict (source, external_id) do nothing;
insert into public.exercises (name_pl, name_en, muscle_groups, primary_muscles, secondary_muscles, equipment, movement_pattern, level, description, mechanic, force, image_urls, image_url, source, external_id, attribution, created_by) values ('Pajacyki', 'Jumping Jacks', array['calves','shoulders','abductors','adductors']::text[], array['calves']::text[], array['shoulders','abductors','adductors']::text[], array['body only']::text[], 'cardio', 'beginner', 'Podskoki z jednoczesnym rozkładaniem nóg i rąk nad głowę. Rozgrzewka i ćwiczenie koordynacji, dobre dla dzieci.', 'compound', 'push', array['https://wger.de/media/exercise-images/320/6c9124b6-3551-47a8-9c22-20141c8b9c53.png','https://wger.de/media/exercise-images/320/85a075aa-53ff-4d61-bad3-5f47e14e0f8e.png']::text[], 'https://wger.de/media/exercise-images/320/6c9124b6-3551-47a8-9c22-20141c8b9c53.png', 'wger', '4d255f25-f199-401a-bc81-7ffab1d0ed24', 'wger.de, autor: student1234, licencja CC-BY-SA 4', null) on conflict (source, external_id) do nothing;
insert into public.exercises (name_pl, name_en, muscle_groups, primary_muscles, secondary_muscles, equipment, movement_pattern, level, description, mechanic, force, image_urls, image_url, source, external_id, attribution, created_by) values ('Pompki w pozycji scyzoryka (pike)', 'Pike Push-Up', array['shoulders','triceps','chest']::text[], array['shoulders']::text[], array['triceps','chest']::text[], array['body only']::text[], 'push_v', 'intermediate', 'Pompka z biodrami wysoko w górze, ciało w odwróconym „V”, głowa schodzi w kierunku podłogi przed dłońmi. Przygotowuje do pompek w staniu na rękach.', 'compound', 'push', array['https://wger.de/media/exercise-images/454/447f3c17-405f-46e0-b138-65c2a8caaab0.png']::text[], 'https://wger.de/media/exercise-images/454/447f3c17-405f-46e0-b138-65c2a8caaab0.png', 'wger', '3b96a05b-9705-48da-b43e-6e098234bb35', 'wger.de, autor: Nash, licencja CC-BY-SA 4', null) on conflict (source, external_id) do nothing;
insert into public.exercises (name_pl, name_en, muscle_groups, primary_muscles, secondary_muscles, equipment, movement_pattern, level, description, mechanic, force, image_urls, image_url, source, external_id, attribution, created_by) values ('Przysiad na jednej nodze (pistolet)', 'Pistol Squat', array['quadriceps','glutes','hamstrings','abdominals']::text[], array['quadriceps']::text[], array['glutes','hamstrings','abdominals']::text[], array['body only']::text[], 'squat', 'advanced', 'Pełny przysiad na jednej nodze z drugą wyprostowaną w przód. Wymaga siły, równowagi i mobilności stawu skokowego – zacznij od przysiadu do skrzyni na jednej nodze.', 'compound', 'push', array['https://wger.de/media/exercise-images/456/3b681e59-377b-40db-9113-ca5873ce084b.jpg','https://wger.de/media/exercise-images/456/c51d875b-0c07-495e-a7cf-08893a9f125d.jpg','https://wger.de/media/exercise-images/456/93716d06-c378-49b8-820a-8bf3e1d7e45c.jpg','https://wger.de/media/exercise-images/456/b8f007b1-d43f-416d-a44b-fb3c15291414.jpg']::text[], 'https://wger.de/media/exercise-images/456/3b681e59-377b-40db-9113-ca5873ce084b.jpg', 'wger', 'fe04cf35-1af5-4b51-89d4-c38d7eaa0db1', 'wger.de, autor: minifigmaster125, licencja CC-BY-SA 3', null) on conflict (source, external_id) do nothing;
insert into public.exercises (name_pl, name_en, muscle_groups, primary_muscles, secondary_muscles, equipment, movement_pattern, level, description, mechanic, force, image_urls, image_url, source, external_id, attribution, created_by) values ('Nordic curl (uginanie nordyckie)', 'Nordic Hamstring Curl', array['hamstrings','glutes','calves']::text[], array['hamstrings']::text[], array['glutes','calves']::text[], array['body only']::text[], 'hinge', 'advanced', 'Z klęku z zablokowanymi piętami powolne opadanie tułowiem w przód na prostych biodrach. Silna praca ekscentryczna dwugłowych – udowodniony wpływ na zapobieganie urazom.', 'isolation', 'pull', array[]::text[], null, 'wger', '9b0f7101-b78a-4c47-b680-fbef15469a8a', 'wger.de, autor: karly, licencja CC-BY-SA 4', null) on conflict (source, external_id) do nothing;
insert into public.exercises (name_pl, name_en, muscle_groups, primary_muscles, secondary_muscles, equipment, movement_pattern, level, description, mechanic, force, image_urls, image_url, source, external_id, attribution, created_by) values ('Odwrócony nordic curl', 'Reverse Nordic Curl', array['quadriceps','abdominals']::text[], array['quadriceps']::text[], array['abdominals']::text[], array['body only']::text[], 'squat', 'intermediate', 'Z klęku odchylanie całego tułowia w tył przy prostych biodrach i powrót. Wzmacnia czworogłowe w wydłużeniu, przydatne przy kolanach i w sportach biegowych.', 'isolation', 'push', array['https://wger.de/media/exercise-images/909/159222d9-c1e4-46ae-89ee-6a2dfaab978d.png']::text[], 'https://wger.de/media/exercise-images/909/159222d9-c1e4-46ae-89ee-6a2dfaab978d.png', 'wger', '6cbdd70c-0691-4288-b58a-24001384f1b3', 'wger.de, autor: karly, licencja CC-BY-SA 4', null) on conflict (source, external_id) do nothing;
insert into public.exercises (name_pl, name_en, muscle_groups, primary_muscles, secondary_muscles, equipment, movement_pattern, level, description, mechanic, force, image_urls, image_url, source, external_id, attribution, created_by) values ('Bird dog (pies myśliwski)', 'Bird Dog', array['lower back','glutes','abdominals','shoulders']::text[], array['lower back']::text[], array['glutes','abdominals','shoulders']::text[], array['body only']::text[], 'core', 'beginner', 'W klęku podpartym jednoczesne wyprostowanie przeciwnej ręki i nogi bez ruchu miednicy. Uczy stabilizacji kręgosłupa – podstawa przy bólu krzyża.', 'compound', 'static', array['https://wger.de/media/exercise-images/1572/3d14e761-a73d-49da-8804-f3016a7573ff.png']::text[], 'https://wger.de/media/exercise-images/1572/3d14e761-a73d-49da-8804-f3016a7573ff.png', 'wger', '6349365e-e901-4280-a1b7-65734986f47d', 'wger.de, autor: Settebello, licencja CC-BY-SA 4', null) on conflict (source, external_id) do nothing;
insert into public.exercises (name_pl, name_en, muscle_groups, primary_muscles, secondary_muscles, equipment, movement_pattern, level, description, mechanic, force, image_urls, image_url, source, external_id, attribution, created_by) values ('Uginanie ramion na taśmach TRX', 'TRX Biceps Curl', array['biceps','forearms','abdominals']::text[], array['biceps']::text[], array['forearms','abdominals']::text[], array['trx']::text[], 'other', 'beginner', 'Z odchylonym ciałem przyciąganie się do uchwytów samym zgięciem łokci. Trudność regulujesz kątem ciała.', 'isolation', 'pull', array['https://wger.de/media/exercise-images/958/947ac249-475d-44ed-bed3-8dc433374f59.png','https://wger.de/media/exercise-images/958/95f2bbc4-2f95-476d-a9b8-81b333fe2ef5.png','https://wger.de/media/exercise-images/958/dfad24f7-3f6f-497c-8436-7dfd909bca3f.png']::text[], 'https://wger.de/media/exercise-images/958/947ac249-475d-44ed-bed3-8dc433374f59.png', 'wger', '596b9d2d-0f01-41a0-97e1-1839ffdb824d', 'wger.de, autor: clafal, licencja CC-BY-SA 4', null) on conflict (source, external_id) do nothing;
insert into public.exercises (name_pl, name_en, muscle_groups, primary_muscles, secondary_muscles, equipment, movement_pattern, level, description, mechanic, force, image_urls, image_url, source, external_id, attribution, created_by) values ('Unoszenie kolan w zwisie', 'Hanging Knee Raise', array['abdominals','forearms']::text[], array['abdominals']::text[], array['forearms']::text[], array['body only']::text[], 'core', 'beginner', 'W zwisie na drążku przyciąganie kolan do klatki z podwinięciem miednicy, bez bujania. Regresja unoszenia prostych nóg.', 'isolation', 'pull', array['https://wger.de/media/exercise-images/978/d3ffe51f-7eb8-4cc9-9eae-105847af3005.png']::text[], 'https://wger.de/media/exercise-images/978/d3ffe51f-7eb8-4cc9-9eae-105847af3005.png', 'wger', 'f4991a98-6422-4884-8ad3-43412f91fac1', 'wger.de, autor: clafal, licencja CC-BY-SA 4', null) on conflict (source, external_id) do nothing;
insert into public.exercises (name_pl, name_en, muscle_groups, primary_muscles, secondary_muscles, equipment, movement_pattern, level, description, mechanic, force, image_urls, image_url, source, external_id, attribution, created_by) values ('Wejścia na podwyższenie bez obciążenia', 'Bodyweight Step-Up', array['quadriceps','glutes','hamstrings','calves']::text[], array['quadriceps']::text[], array['glutes','hamstrings','calves']::text[], array['body only']::text[], 'lunge', 'beginner', 'Wejście na skrzynię lub ławkę jedną nogą, pełny wyprost na górze i kontrolowane zejście. Pracuje noga na podwyższeniu – nie odbijaj się tylną.', 'compound', 'push', array['https://wger.de/media/exercise-images/981/f9377a7e-eb58-4cca-b805-2d36863aeb03.png']::text[], 'https://wger.de/media/exercise-images/981/f9377a7e-eb58-4cca-b805-2d36863aeb03.png', 'wger', '9e6dae29-5d03-440a-bdf1-2cb25a5179c2', 'wger.de, autor: społeczność wger, licencja CC-BY-SA 4', null) on conflict (source, external_id) do nothing;
insert into public.exercises (name_pl, name_en, muscle_groups, primary_muscles, secondary_muscles, equipment, movement_pattern, level, description, mechanic, force, image_urls, image_url, source, external_id, attribution, created_by) values ('Wykroki w miejscu bez obciążenia', 'Bodyweight Lunge', array['quadriceps','glutes','hamstrings']::text[], array['quadriceps']::text[], array['glutes','hamstrings']::text[], array['body only']::text[], 'lunge', 'beginner', 'Wykrok w przód i powrót, tylne kolano nisko nad podłogą. Pierwszy krok do wykroków z obciążeniem.', 'compound', 'push', array[]::text[], null, 'wger', 'f9a0a918-3c0c-464e-bbba-1bd309d4a519', 'wger.de, autor: hektkaso, licencja CC-BY-SA 4', null) on conflict (source, external_id) do nothing;
insert into public.exercises (name_pl, name_en, muscle_groups, primary_muscles, secondary_muscles, equipment, movement_pattern, level, description, mechanic, force, image_urls, image_url, source, external_id, attribution, created_by) values ('Przysiad bułgarski bez obciążenia', 'Bodyweight Bulgarian Split Squat', array['quadriceps','glutes','hamstrings','adductors']::text[], array['quadriceps']::text[], array['glutes','hamstrings','adductors']::text[], array['body only']::text[], 'lunge', 'intermediate', 'Przysiad na przedniej nodze z tylną stopą na ławce. Tułów lekko pochylony, kolano przodem nad stopą.', 'compound', 'push', array['https://wger.de/media/exercise-images/988/6283b258-a4d7-4833-84f7-a38987022d3d.png']::text[], 'https://wger.de/media/exercise-images/988/6283b258-a4d7-4833-84f7-a38987022d3d.png', 'wger', '7ce489d2-1948-46de-aa80-277b2ca737aa', 'wger.de, autor: społeczność wger, licencja CC-BY-SA 4', null) on conflict (source, external_id) do nothing;
insert into public.exercises (name_pl, name_en, muscle_groups, primary_muscles, secondary_muscles, equipment, movement_pattern, level, description, mechanic, force, image_urls, image_url, source, external_id, attribution, created_by) values ('Wykopy nogi w tył w klęku', 'Donkey Kick', array['glutes','hamstrings','lower back']::text[], array['glutes']::text[], array['hamstrings','lower back']::text[], array['body only']::text[], 'hinge', 'beginner', 'W klęku podpartym unoszenie zgiętej nogi piętą do sufitu bez wyginania lędźwi. Aktywacja pośladka przed treningiem nóg.', 'isolation', 'push', array['https://wger.de/media/exercise-images/990/de20457c-914a-45c9-8cf9-0ad9739759a1.png']::text[], 'https://wger.de/media/exercise-images/990/de20457c-914a-45c9-8cf9-0ad9739759a1.png', 'wger', '6ddea666-5a57-4ac0-926f-01f8cfdaa4fd', 'wger.de, autor: społeczność wger, licencja CC-BY-SA 4', null) on conflict (source, external_id) do nothing;
insert into public.exercises (name_pl, name_en, muscle_groups, primary_muscles, secondary_muscles, equipment, movement_pattern, level, description, mechanic, force, image_urls, image_url, source, external_id, attribution, created_by) values ('Wykroki w tył bez obciążenia', 'Bodyweight Reverse Lunge', array['quadriceps','glutes','hamstrings']::text[], array['quadriceps']::text[], array['glutes','hamstrings']::text[], array['body only']::text[], 'lunge', 'beginner', 'Krok w tył do wykroku i powrót. Łagodniejszy dla kolan niż wykrok w przód – dobry na start.', 'compound', 'push', array['https://wger.de/media/exercise-images/999/d0931eb3-8db0-4049-bb08-aa4036072056.jfif','https://wger.de/media/exercise-images/999/8548b2d2-004d-48b4-95fd-b1b25f4e53d0.jfif']::text[], 'https://wger.de/media/exercise-images/999/d0931eb3-8db0-4049-bb08-aa4036072056.jfif', 'wger', '616f9026-1a1d-4ed8-b068-cfbb81b6a000', 'wger.de, autor: społeczność wger, licencja CC-BY-SA 4', null) on conflict (source, external_id) do nothing;
insert into public.exercises (name_pl, name_en, muscle_groups, primary_muscles, secondary_muscles, equipment, movement_pattern, level, description, mechanic, force, image_urls, image_url, source, external_id, attribution, created_by) values ('Martwy ciąg z kettlebell', 'Kettlebell Deadlift', array['glutes','hamstrings','lower back','quadriceps','forearms']::text[], array['glutes']::text[], array['hamstrings','lower back','quadriceps','forearms']::text[], array['kettlebells']::text[], 'hinge', 'beginner', 'Kettlebell między stopami, biodra w tył, proste plecy, wstajemy wypychając biodra w przód. Nauka wzorca zawiasu biodrowego przed sztangą.', 'compound', 'pull', array['https://wger.de/media/exercise-images/1003/772d6e47-3865-4944-9255-7435d0b06782.png','https://wger.de/media/exercise-images/1003/a2b47fa8-79b4-4a21-920b-48765f562bc4.png']::text[], 'https://wger.de/media/exercise-images/1003/772d6e47-3865-4944-9255-7435d0b06782.png', 'wger', '9b5f8c6e-2436-4ded-aea9-8c698b0c8768', 'wger.de, autor: społeczność wger, licencja CC-BY-SA 4', null) on conflict (source, external_id) do nothing;
insert into public.exercises (name_pl, name_en, muscle_groups, primary_muscles, secondary_muscles, equipment, movement_pattern, level, description, mechanic, force, image_urls, image_url, source, external_id, attribution, created_by) values ('Pompki hinduskie', 'Hindu Push-Up', array['chest','shoulders','triceps','lower back']::text[], array['chest']::text[], array['shoulders','triceps','lower back']::text[], array['body only']::text[], 'push_h', 'intermediate', 'Płynne przejście z pozycji scyzoryka nurkowaniem przez pompkę do wygięcia tułowia w górę. Siła i mobilność barków.', 'compound', 'push', array['https://wger.de/media/exercise-images/1080/c4bf7ba1-6058-4d14-928f-7187885d5d57.webp']::text[], 'https://wger.de/media/exercise-images/1080/c4bf7ba1-6058-4d14-928f-7187885d5d57.webp', 'wger', '476c1d96-6590-4f86-98f0-3f12808fab53', 'wger.de, autor: Imobard, licencja CC-BY-SA 4', null) on conflict (source, external_id) do nothing;
insert into public.exercises (name_pl, name_en, muscle_groups, primary_muscles, secondary_muscles, equipment, movement_pattern, level, description, mechanic, force, image_urls, image_url, source, external_id, attribution, created_by) values ('Martwy ciąg sumo z hantlem', 'Dumbbell Sumo Deadlift', array['glutes','adductors','quadriceps','hamstrings']::text[], array['glutes']::text[], array['adductors','quadriceps','hamstrings']::text[], array['dumbbell']::text[], 'hinge', 'beginner', 'Szeroki rozstaw stóp, hantel trzymany pionowo między nogami, proste plecy, wstajemy wypychając biodra. Łatwy start w ciągach.', 'compound', 'pull', array['https://wger.de/media/exercise-images/1088/9f66b288-ce8f-4154-ba80-78fee267263c.jpg']::text[], 'https://wger.de/media/exercise-images/1088/9f66b288-ce8f-4154-ba80-78fee267263c.jpg', 'wger', '0c30c543-e2cc-499b-bc31-8c28db445ed2', 'wger.de, autor: philip, licencja CC-BY-SA 4', null) on conflict (source, external_id) do nothing;
insert into public.exercises (name_pl, name_en, muscle_groups, primary_muscles, secondary_muscles, equipment, movement_pattern, level, description, mechanic, force, image_urls, image_url, source, external_id, attribution, created_by) values ('Martwy ciąg sumo z kettlebell', 'Kettlebell Sumo Deadlift', array['glutes','adductors','quadriceps','hamstrings']::text[], array['glutes']::text[], array['adductors','quadriceps','hamstrings']::text[], array['kettlebells']::text[], 'hinge', 'beginner', 'Kettlebell między stopami w szerokim rozstawie, kolana na zewnątrz, plecy proste. Regresja martwego ciągu sumo ze sztangą.', 'compound', 'pull', array['https://wger.de/media/exercise-images/1612/3dc33f57-2786-4305-8b91-e011d7055923.jpg','https://wger.de/media/exercise-images/1612/e719b872-d122-4e2d-be17-bd2babfe457a.jpg']::text[], 'https://wger.de/media/exercise-images/1612/3dc33f57-2786-4305-8b91-e011d7055923.jpg', 'wger', '5cbaa028-114d-4a15-9a95-70d9b3146f30', 'wger.de, autor: Tierrasverdes, licencja CC-BY-SA 4', null) on conflict (source, external_id) do nothing;
insert into public.exercises (name_pl, name_en, muscle_groups, primary_muscles, secondary_muscles, equipment, movement_pattern, level, description, mechanic, force, image_urls, image_url, source, external_id, attribution, created_by) values ('Deska z dotykaniem barków', 'Plank Shoulder Taps', array['abdominals','shoulders','chest']::text[], array['abdominals']::text[], array['shoulders','chest']::text[], array['body only']::text[], 'core', 'beginner', 'W podporze na prostych rękach naprzemienne dotykanie przeciwnego barku bez kołysania biodrami. Stabilizacja antyrotacyjna.', 'compound', 'static', array['https://wger.de/media/exercise-images/1091/50c8912d-54ef-46c9-99d1-633b6196aa1e.jpg']::text[], 'https://wger.de/media/exercise-images/1091/50c8912d-54ef-46c9-99d1-633b6196aa1e.jpg', 'wger', '75d730d0-3b26-4a25-8f1a-7119a98e02ef', 'wger.de, autor: clafal, licencja CC-BY-SA 4', null) on conflict (source, external_id) do nothing;
insert into public.exercises (name_pl, name_en, muscle_groups, primary_muscles, secondary_muscles, equipment, movement_pattern, level, description, mechanic, force, image_urls, image_url, source, external_id, attribution, created_by) values ('Wall ball (rzut piłką do ściany)', 'Wall Ball', array['quadriceps','glutes','shoulders','triceps']::text[], array['quadriceps']::text[], array['glutes','shoulders','triceps']::text[], array['medicine ball']::text[], 'squat', 'intermediate', 'Przysiad z piłką lekarską przy klatce i dynamiczny wyrzut piłki do celu na ścianie. Kondycja i moc całego ciała.', 'compound', 'push', array['https://wger.de/media/exercise-images/1100/ab203e0c-8220-4537-987c-871eb259d687.jpg']::text[], 'https://wger.de/media/exercise-images/1100/ab203e0c-8220-4537-987c-871eb259d687.jpg', 'wger', 'f20ab712-f953-4705-8710-9681392ddd07', 'wger.de, autor: philip, licencja CC-BY-SA 4', null) on conflict (source, external_id) do nothing;
insert into public.exercises (name_pl, name_en, muscle_groups, primary_muscles, secondary_muscles, equipment, movement_pattern, level, description, mechanic, force, image_urls, image_url, source, external_id, attribution, created_by) values ('Wyciskanie hantli złączonych (hex press)', 'Dumbbell Hex Press', array['chest','triceps','shoulders']::text[], array['chest']::text[], array['triceps','shoulders']::text[], array['dumbbell']::text[], 'push_h', 'beginner', 'Wyciskanie leżąc z hantlami dociśniętymi do siebie przez cały ruch. Mocne napięcie środkowej części klatki.', 'compound', 'push', array['https://wger.de/media/exercise-images/1353/138cb483-7d4d-4519-b029-63e4269810a6.webp']::text[], 'https://wger.de/media/exercise-images/1353/138cb483-7d4d-4519-b029-63e4269810a6.webp', 'wger', '587af8f1-516b-44c3-8660-70f262e1bef8', 'wger.de, autor: Anastasious, licencja CC-BY-SA 4', null) on conflict (source, external_id) do nothing;
insert into public.exercises (name_pl, name_en, muscle_groups, primary_muscles, secondary_muscles, equipment, movement_pattern, level, description, mechanic, force, image_urls, image_url, source, external_id, attribution, created_by) values ('Devil press', 'Devil''s Press', array['shoulders','glutes','hamstrings','chest','triceps']::text[], array['shoulders']::text[], array['glutes','hamstrings','chest','triceps']::text[], array['dumbbell']::text[], 'push_v', 'advanced', 'Burpee z hantlami zakończone wyrzutem hantli z ziemi nad głowę jednym ruchem. Wymagające ćwiczenie kondycyjno-siłowe.', 'compound', 'push', array['https://wger.de/media/exercise-images/1556/a23c820b-e08b-4911-a6a4-80f16c15d2e0.png']::text[], 'https://wger.de/media/exercise-images/1556/a23c820b-e08b-4911-a6a4-80f16c15d2e0.png', 'wger', 'bb9b994e-426f-4693-9d16-3f8d5a9c72b8', 'wger.de, autor: Settebello, licencja CC-BY-SA 4', null) on conflict (source, external_id) do nothing;
insert into public.exercises (name_pl, name_en, muscle_groups, primary_muscles, secondary_muscles, equipment, movement_pattern, level, description, mechanic, force, image_urls, image_url, source, external_id, attribution, created_by) values ('Wiosłowanie hantlem w pozycji bird dog', 'Bird Dog Row', array['middle back','lats','lower back','abdominals']::text[], array['middle back']::text[], array['lats','lower back','abdominals']::text[], array['dumbbell']::text[], 'pull_h', 'intermediate', 'Na ławce w podporze jednostronnym wiosłowanie z jednoczesnym utrzymaniem stabilnego tułowia. Łączy plecy i stabilizację.', 'compound', 'pull', array[]::text[], null, 'library', 'bird-dog-row', null, null) on conflict (source, external_id) do nothing;
insert into public.exercises (name_pl, name_en, muscle_groups, primary_muscles, secondary_muscles, equipment, movement_pattern, level, description, mechanic, force, image_urls, image_url, source, external_id, attribution, created_by) values ('Przysiad przedni z hantlami', 'Dumbbell Front Squat', array['quadriceps','glutes','abdominals']::text[], array['quadriceps']::text[], array['glutes','abdominals']::text[], array['dumbbell']::text[], 'squat', 'beginner', 'Hantle oparte na barkach, łokcie wysoko, przysiad z wyprostowanym tułowiem. Alternatywa przysiadu przedniego bez sztangi.', 'compound', 'push', array['https://wger.de/media/exercise-images/1640/bdea82f1-15ef-4649-8b5a-1303cfc178e7.webp']::text[], 'https://wger.de/media/exercise-images/1640/bdea82f1-15ef-4649-8b5a-1303cfc178e7.webp', 'wger', '4621b41f-0d32-4033-acff-dc079c792606', 'wger.de, autor: AlucardEvil40, licencja CC-BY-SA 4', null) on conflict (source, external_id) do nothing;
insert into public.exercises (name_pl, name_en, muscle_groups, primary_muscles, secondary_muscles, equipment, movement_pattern, level, description, mechanic, force, image_urls, image_url, source, external_id, attribution, created_by) values ('Hip thrust z hantlem', 'Dumbbell Hip Thrust', array['glutes','hamstrings']::text[], array['glutes']::text[], array['hamstrings']::text[], array['dumbbell']::text[], 'hinge', 'beginner', 'Łopatki na ławce, hantel na biodrach, wypchnięcie bioder do linii barki–kolana i napięcie pośladków na górze. Regresja hip thrustu ze sztangą.', 'isolation', 'push', array['https://wger.de/media/exercise-images/1642/a81ad922-caf5-47f8-99b4-640cb0717436.webp']::text[], 'https://wger.de/media/exercise-images/1642/a81ad922-caf5-47f8-99b4-640cb0717436.webp', 'wger', 'af77220c-098c-47c2-9f8c-92a651998903', 'wger.de, autor: AlucardEvil40, licencja CC-BY-SA 4', null) on conflict (source, external_id) do nothing;
insert into public.exercises (name_pl, name_en, muscle_groups, primary_muscles, secondary_muscles, equipment, movement_pattern, level, description, mechanic, force, image_urls, image_url, source, external_id, attribution, created_by) values ('Martwy ciąg rumuński z hantlami', 'Dumbbell Romanian Deadlift', array['hamstrings','glutes','lower back']::text[], array['hamstrings']::text[], array['glutes','lower back']::text[], array['dumbbell']::text[], 'hinge', 'beginner', 'Lekko ugięte kolana, hantle prowadzone blisko ud, biodra daleko w tył do czucia rozciągnięcia dwugłowych. Plecy proste przez cały ruch.', 'compound', 'pull', array['https://wger.de/media/exercise-images/1652/0306c8c0-70cc-45d4-92de-6fa72ceaa834.webp']::text[], 'https://wger.de/media/exercise-images/1652/0306c8c0-70cc-45d4-92de-6fa72ceaa834.webp', 'wger', '65d12ecf-54b8-466d-a412-e55c396cad69', 'wger.de, autor: AlucardEvil40, licencja CC-BY-SA 4', null) on conflict (source, external_id) do nothing;
insert into public.exercises (name_pl, name_en, muscle_groups, primary_muscles, secondary_muscles, equipment, movement_pattern, level, description, mechanic, force, image_urls, image_url, source, external_id, attribution, created_by) values ('Przysiad bułgarski z hantlami', 'Dumbbell Bulgarian Split Squat', array['quadriceps','glutes','hamstrings','adductors']::text[], array['quadriceps']::text[], array['glutes','hamstrings','adductors']::text[], array['dumbbell']::text[], 'lunge', 'intermediate', 'Tylna stopa na ławce, hantle w dłoniach, przysiad na przedniej nodze. Jedno z najlepszych ćwiczeń jednostronnych na nogi i pośladki.', 'compound', 'push', array['https://wger.de/media/exercise-images/1706/0c5243cc-2539-4005-aee0-d3a8c5d3a32c.jfif']::text[], 'https://wger.de/media/exercise-images/1706/0c5243cc-2539-4005-aee0-d3a8c5d3a32c.jfif', 'wger', '60d2c34b-43a1-48a3-b43b-160e4c0157f2', 'wger.de, autor: AlucardEvil40, licencja CC-BY-SA 4', null) on conflict (source, external_id) do nothing;
insert into public.exercises (name_pl, name_en, muscle_groups, primary_muscles, secondary_muscles, equipment, movement_pattern, level, description, mechanic, force, image_urls, image_url, source, external_id, attribution, created_by) values ('Martwy ciąg rumuński na jednej nodze z hantlem', 'Single-Leg Dumbbell Romanian Deadlift', array['hamstrings','glutes','lower back','abductors']::text[], array['hamstrings']::text[], array['glutes','lower back','abductors']::text[], array['dumbbell']::text[], 'hinge', 'intermediate', 'Skłon na jednej nodze z hantlem, wolna noga idzie w tył w linii z tułowiem, biodra równo. Siła tylnej taśmy i równowaga.', 'compound', 'pull', array['https://wger.de/media/exercise-images/1736/aa724cc5-c485-4f3e-9d2a-0c6ae4baefbe.png']::text[], 'https://wger.de/media/exercise-images/1736/aa724cc5-c485-4f3e-9d2a-0c6ae4baefbe.png', 'wger', 'a630de17-9170-434c-b486-96a6b8705506', 'wger.de, autor: Tierrasverdes, licencja CC-BY-SA 4', null) on conflict (source, external_id) do nothing;
insert into public.exercises (name_pl, name_en, muscle_groups, primary_muscles, secondary_muscles, equipment, movement_pattern, level, description, mechanic, force, image_urls, image_url, source, external_id, attribution, created_by) values ('Mobilizacja stawu skokowego (kolano do ściany)', 'Ankle Dorsiflexion Rocks', array['calves']::text[], array['calves']::text[], array[]::text[], array['body only']::text[], 'mobility', 'beginner', 'W wykroku przy ścianie przesuwanie kolana w przód nad palce bez odrywania pięty. Poprawia głębokość przysiadu i ustawienie kolan.', 'isolation', 'static', array['https://wger.de/media/exercise-images/1804/691c69b8-c3db-4177-8435-dd3a97d88542.webp']::text[], 'https://wger.de/media/exercise-images/1804/691c69b8-c3db-4177-8435-dd3a97d88542.webp', 'wger', 'fa5252d3-973c-4b35-9324-a02460545283', 'wger.de, autor: Davidgj32, licencja CC-BY-SA 4', null) on conflict (source, external_id) do nothing;
insert into public.exercises (name_pl, name_en, muscle_groups, primary_muscles, secondary_muscles, equipment, movement_pattern, level, description, mechanic, force, image_urls, image_url, source, external_id, attribution, created_by) values ('Wykroki w tył ze sztangą', 'Barbell Reverse Lunge', array['quadriceps','glutes','hamstrings','adductors']::text[], array['quadriceps']::text[], array['glutes','hamstrings','adductors']::text[], array['barbell']::text[], 'lunge', 'intermediate', 'Sztanga na plecach, krok w tył do wykroku i powrót. Stabilniejsze i łagodniejsze dla kolan niż wykrok w przód.', 'compound', 'push', array['https://wger.de/media/exercise-images/1830/3b6c547c-ab3d-4472-93cf-561710279eab.jpg']::text[], 'https://wger.de/media/exercise-images/1830/3b6c547c-ab3d-4472-93cf-561710279eab.jpg', 'wger', '928eeae3-d849-4605-a470-048ca259a8c5', 'wger.de, autor: społeczność wger, licencja CC-BY-SA 4', null) on conflict (source, external_id) do nothing;
insert into public.exercises (name_pl, name_en, muscle_groups, primary_muscles, secondary_muscles, equipment, movement_pattern, level, description, mechanic, force, image_urls, image_url, source, external_id, attribution, created_by) values ('Pompki z obciążeniem', 'Weighted Push-Up', array['chest','triceps','shoulders']::text[], array['chest']::text[], array['triceps','shoulders']::text[], array['other']::text[], 'push_h', 'advanced', 'Pompka z talerzem na plecach albo w kamizelce obciążeniowej. Progresja, gdy klient robi ponad 20 czystych pompek.', 'compound', 'push', array['https://wger.de/media/exercise-images/1902/d0c3f170-543c-4be4-bc70-5c6dc606406c.png']::text[], 'https://wger.de/media/exercise-images/1902/d0c3f170-543c-4be4-bc70-5c6dc606406c.png', 'wger', '37abbe32-2fab-4818-8355-fffcff2dc3e3', 'wger.de, autor: nishant0712, licencja CC-BY-SA 4', null) on conflict (source, external_id) do nothing;
insert into public.exercises (name_pl, name_en, muscle_groups, primary_muscles, secondary_muscles, equipment, movement_pattern, level, description, mechanic, force, image_urls, image_url, source, external_id, attribution, created_by) values ('Planche w skulonej pozycji (tuck)', 'Tuck Planche', array['shoulders','chest','triceps','abdominals']::text[], array['shoulders']::text[], array['chest','triceps','abdominals']::text[], array['body only']::text[], 'push_h', 'advanced', 'Podpór na prostych rękach z kolanami przy klatce i biodrami na wysokości barków. Zaawansowana statyka kalisteniczna.', 'isolation', 'static', array['https://wger.de/media/exercise-images/1916/e7d97b4b-9fe4-4378-aea3-5a9d93b6eb8d.png']::text[], 'https://wger.de/media/exercise-images/1916/e7d97b4b-9fe4-4378-aea3-5a9d93b6eb8d.png', 'wger', '3e9973f6-c218-4dd4-850b-da6f4f1622bb', 'wger.de, autor: ISSACS, licencja CC-BY-SA 4', null) on conflict (source, external_id) do nothing;
insert into public.exercises (name_pl, name_en, muscle_groups, primary_muscles, secondary_muscles, equipment, movement_pattern, level, description, mechanic, force, image_urls, image_url, source, external_id, attribution, created_by) values ('Rwanie hantla jednorącz', 'Dumbbell Snatch', array['shoulders','glutes','hamstrings','quadriceps','traps']::text[], array['shoulders']::text[], array['glutes','hamstrings','quadriceps','traps']::text[], array['dumbbell']::text[], 'hinge', 'intermediate', 'Dynamiczny wyrzut hantla z podłogi nad głowę jednym ruchem z pracy bioder. Moc i koordynacja.', 'compound', 'pull', array['https://wger.de/media/exercise-images/1947/4201a9c0-f9e4-48ca-80f1-b46c7ffe5640.webp']::text[], 'https://wger.de/media/exercise-images/1947/4201a9c0-f9e4-48ca-80f1-b46c7ffe5640.webp', 'wger', '51fe0871-1390-4755-bd04-01a93e32f533', 'wger.de, autor: Aleid, licencja CC-BY-SA 4', null) on conflict (source, external_id) do nothing;
insert into public.exercises (name_pl, name_en, muscle_groups, primary_muscles, secondary_muscles, equipment, movement_pattern, level, description, mechanic, force, image_urls, image_url, source, external_id, attribution, created_by) values ('Końcowy wyprost kolana z gumą (TKE)', 'Band Terminal Knee Extension', array['quadriceps']::text[], array['quadriceps']::text[], array[]::text[], array['bands']::text[], 'other', 'beginner', 'Guma za kolanem, dopychanie kolana do pełnego wyprostu i chwila napięcia. Klasyka rehabilitacji kolana i aktywacja przyśrodkowej głowy czworogłowego.', 'isolation', 'push', array['https://wger.de/media/exercise-images/2494/02f1ae86-d374-4b5a-b314-a76c487ea1e9.png','https://wger.de/media/exercise-images/2494/2213ff47-94e8-4884-919f-5af8a2fe9c0f.png']::text[], 'https://wger.de/media/exercise-images/2494/02f1ae86-d374-4b5a-b314-a76c487ea1e9.png', 'wger', '3096b34e-1781-4f99-8187-d9acac8e712b', 'wger.de, autor: Rehab Hero, licencja CC-BY-SA 4', null) on conflict (source, external_id) do nothing;
insert into public.exercises (name_pl, name_en, muscle_groups, primary_muscles, secondary_muscles, equipment, movement_pattern, level, description, mechanic, force, image_urls, image_url, source, external_id, attribution, created_by) values ('Pompki łopatkowe', 'Scapular Push-Up', array['shoulders','chest']::text[], array['shoulders']::text[], array['chest']::text[], array['body only']::text[], 'push_h', 'beginner', 'W podporze na prostych rękach samo ściąganie i rozsuwanie łopatek. Wzmacnia zębaty przedni, przydatne przy problemach z barkiem.', 'isolation', 'push', array['https://wger.de/media/exercise-images/2681/d4f89553-c920-4748-8302-9bd30b4f4c4d.png','https://wger.de/media/exercise-images/2681/c787822b-e5ad-415b-a686-af2f18133b3c.png']::text[], 'https://wger.de/media/exercise-images/2681/d4f89553-c920-4748-8302-9bd30b4f4c4d.png', 'wger', 'e044cd7d-ef86-4154-a3a8-bd01fc5535ab', 'wger.de, autor: nalhilal, licencja CC-BY-SA 4', null) on conflict (source, external_id) do nothing;
insert into public.exercises (name_pl, name_en, muscle_groups, primary_muscles, secondary_muscles, equipment, movement_pattern, level, description, mechanic, force, image_urls, image_url, source, external_id, attribution, created_by) values ('Thruster ze sztangą', 'Barbell Thruster', array['quadriceps','shoulders','glutes','triceps']::text[], array['quadriceps']::text[], array['shoulders','glutes','triceps']::text[], array['barbell']::text[], 'squat', 'intermediate', 'Przysiad przedni przechodzący płynnie w wyciskanie nad głowę z wykorzystaniem wybicia z nóg. Ćwiczenie kondycyjne całego ciała.', 'compound', 'push', array[]::text[], null, 'wger', '51420ded-5c17-4ce0-b005-89f1b67b7c65', 'wger.de, autor: BeLikeWater, licencja CC0', null) on conflict (source, external_id) do nothing;
insert into public.exercises (name_pl, name_en, muscle_groups, primary_muscles, secondary_muscles, equipment, movement_pattern, level, description, mechanic, force, image_urls, image_url, source, external_id, attribution, created_by) values ('Thruster z hantlami', 'Dumbbell Thruster', array['quadriceps','shoulders','glutes','triceps']::text[], array['quadriceps']::text[], array['shoulders','glutes','triceps']::text[], array['dumbbell']::text[], 'squat', 'beginner', 'Przysiad z hantlami na barkach i wyciśnięcie ich nad głowę jednym ruchem. Łatwiejsza wersja thrustera ze sztangą.', 'compound', 'push', array[]::text[], null, 'wger', 'ae6a522e-db10-45ba-9642-987468d8a4de', 'wger.de, autor: meldun, licencja CC-BY-SA 4', null) on conflict (source, external_id) do nothing;
insert into public.exercises (name_pl, name_en, muscle_groups, primary_muscles, secondary_muscles, equipment, movement_pattern, level, description, mechanic, force, image_urls, image_url, source, external_id, attribution, created_by) values ('Wstawanie tureckie (Turkish get-up)', 'Turkish Get-Up', array['shoulders','abdominals','glutes','quadriceps']::text[], array['shoulders']::text[], array['abdominals','glutes','quadriceps']::text[], array['kettlebells']::text[], 'other', 'intermediate', 'Wstanie z leżenia do stania z ciężarem trzymanym nad głową na prostej ręce, krok po kroku, i powrót. Stabilność barku i całego ciała.', 'compound', 'push', array[]::text[], null, 'wger', '309bfd2b-1af4-49db-b64b-d7d7c7dd39bb', 'wger.de, autor: dookie1481, licencja CC-BY-SA 4', null) on conflict (source, external_id) do nothing;
insert into public.exercises (name_pl, name_en, muscle_groups, primary_muscles, secondary_muscles, equipment, movement_pattern, level, description, mechanic, force, image_urls, image_url, source, external_id, attribution, created_by) values ('Pompki na kolanach', 'Knee Push-Up', array['chest','triceps','shoulders']::text[], array['chest']::text[], array['triceps','shoulders']::text[], array['body only']::text[], 'push_h', 'beginner', 'Pompka z podparciem na kolanach, ciało proste od kolan do głowy. Regresja klasycznej pompki.', 'compound', 'push', array[]::text[], null, 'wger', '2b61df61-f71e-4b8f-9f95-6a565238a8ae', 'wger.de, autor: PaukOne, licencja CC-BY-SA 4', null) on conflict (source, external_id) do nothing;
insert into public.exercises (name_pl, name_en, muscle_groups, primary_muscles, secondary_muscles, equipment, movement_pattern, level, description, mechanic, force, image_urls, image_url, source, external_id, attribution, created_by) values ('Przysiad kozacki', 'Cossack Squat', array['adductors','quadriceps','glutes','hamstrings']::text[], array['adductors']::text[], array['quadriceps','glutes','hamstrings']::text[], array['body only']::text[], 'squat', 'intermediate', 'Szeroki rozkrok, przysiad na jedną nogę z drugą wyprostowaną w bok i palcami do góry. Siła i mobilność przywodzicieli oraz bioder.', 'compound', 'push', array[]::text[], null, 'wger', '96a899ee-16a4-457d-8f66-efdd39fd38a0', 'wger.de, autor: clafal, licencja CC-BY-SA 4', null) on conflict (source, external_id) do nothing;
insert into public.exercises (name_pl, name_en, muscle_groups, primary_muscles, secondary_muscles, equipment, movement_pattern, level, description, mechanic, force, image_urls, image_url, source, external_id, attribution, created_by) values ('Krzesełko przy ścianie', 'Wall Sit', array['quadriceps','glutes']::text[], array['quadriceps']::text[], array['glutes']::text[], array['body only']::text[], 'squat', 'beginner', 'Utrzymanie przysiadu z plecami przy ścianie i kątem ok. 90° w kolanach. Izometria czworogłowych, często w rehabilitacji kolana.', 'isolation', 'static', array[]::text[], null, 'wger', '3f8ad988-1aee-48ca-ad37-44e39ae1715d', 'wger.de, autor: clafal, licencja CC-BY-SA 4', null) on conflict (source, external_id) do nothing;
insert into public.exercises (name_pl, name_en, muscle_groups, primary_muscles, secondary_muscles, equipment, movement_pattern, level, description, mechanic, force, image_urls, image_url, source, external_id, attribution, created_by) values ('Dragon flag', 'Dragon Flag', array['abdominals','lower back','lats']::text[], array['abdominals']::text[], array['lower back','lats']::text[], array['body only']::text[], 'core', 'advanced', 'Leżąc na ławce i trzymając się za głową, opuszczanie sztywnego ciała opartego tylko na łopatkach. Bardzo zaawansowane ćwiczenie brzucha.', 'compound', 'static', array[]::text[], null, 'wger', 'f5ad82a8-adf8-4795-9874-1f6d183c56ed', 'wger.de, autor: clafal, licencja CC-BY-SA 4', null) on conflict (source, external_id) do nothing;
insert into public.exercises (name_pl, name_en, muscle_groups, primary_muscles, secondary_muscles, equipment, movement_pattern, level, description, mechanic, force, image_urls, image_url, source, external_id, attribution, created_by) values ('Deska kopenhaska', 'Copenhagen Adduction', array['adductors','abdominals','abductors']::text[], array['adductors']::text[], array['abdominals','abductors']::text[], array['body only']::text[], 'core', 'intermediate', 'Deska boczna z górną nogą opartą na ławce. Wzmacnia przywodziciele – profilaktyka urazów pachwiny w sportach z bieganiem.', 'isolation', 'static', array[]::text[], null, 'wger', 'dbed4613-e1d5-483f-90ae-6db5d593911e', 'wger.de, autor: RiccaBaro, licencja CC-BY-SA 4', null) on conflict (source, external_id) do nothing;
insert into public.exercises (name_pl, name_en, muscle_groups, primary_muscles, secondary_muscles, equipment, movement_pattern, level, description, mechanic, force, image_urls, image_url, source, external_id, attribution, created_by) values ('Spacer z ciężarem w jednej ręce', 'Suitcase Carry', array['abdominals','forearms','traps','glutes']::text[], array['abdominals']::text[], array['forearms','traps','glutes']::text[], array['dumbbell']::text[], 'carry', 'beginner', 'Marsz z ciężkim hantlem lub kettlebell w jednej ręce, tułów prosto bez przechylania. Stabilizacja boczna tułowia i chwyt.', 'compound', 'static', array[]::text[], null, 'wger', 'b6c19c36-34be-4d9f-8c07-8bdf9ab3ba1a', 'wger.de, autor: aboksz, licencja CC-BY-SA 4', null) on conflict (source, external_id) do nothing;
insert into public.exercises (name_pl, name_en, muscle_groups, primary_muscles, secondary_muscles, equipment, movement_pattern, level, description, mechanic, force, image_urls, image_url, source, external_id, attribution, created_by) values ('Muszelka (clamshell)', 'Clamshell', array['abductors','glutes']::text[], array['abductors']::text[], array['glutes']::text[], array['body only']::text[], 'other', 'beginner', 'Leżenie na boku z ugiętymi nogami, unoszenie górnego kolana bez rotacji miednicy. Aktywacja pośladka średniego.', 'isolation', 'pull', array[]::text[], null, 'wger', 'ca3ca5d0-5231-4420-ad06-fa3d32693a1b', 'wger.de, autor: teus_ergaster, licencja CC-BY-SA 4', null) on conflict (source, external_id) do nothing;
insert into public.exercises (name_pl, name_en, muscle_groups, primary_muscles, secondary_muscles, equipment, movement_pattern, level, description, mechanic, force, image_urls, image_url, source, external_id, attribution, created_by) values ('Muszelka z gumą', 'Banded Clamshell', array['abductors','glutes']::text[], array['abductors']::text[], array['glutes']::text[], array['bands']::text[], 'other', 'beginner', 'Muszelka z mini-gumą nad kolanami. Progresja muszelki – przydatna przy koślawieniu kolan.', 'isolation', 'pull', array[]::text[], null, 'wger', '8cc84753-e638-4c43-91c6-51c097813ca4', 'wger.de, autor: Croak6728, licencja CC-BY-SA 4', null) on conflict (source, external_id) do nothing;
insert into public.exercises (name_pl, name_en, muscle_groups, primary_muscles, secondary_muscles, equipment, movement_pattern, level, description, mechanic, force, image_urls, image_url, source, external_id, attribution, created_by) values ('L-sit', 'L-Sit', array['abdominals','triceps','quadriceps','shoulders']::text[], array['abdominals']::text[], array['triceps','quadriceps','shoulders']::text[], array['body only']::text[], 'core', 'advanced', 'Podpór na prostych rękach z prostymi nogami uniesionymi poziomo. Siła brzucha i zginaczy bioder, kompresja.', 'isolation', 'static', array[]::text[], null, 'wger', '16202754-f567-4d23-a866-2c9cc8eba71d', 'wger.de, autor: Croak6728, licencja CC-BY-SA 4', null) on conflict (source, external_id) do nothing;
insert into public.exercises (name_pl, name_en, muscle_groups, primary_muscles, secondary_muscles, equipment, movement_pattern, level, description, mechanic, force, image_urls, image_url, source, external_id, attribution, created_by) values ('L-sit w skulonej pozycji', 'Tuck L-Sit', array['abdominals','triceps','shoulders']::text[], array['abdominals']::text[], array['triceps','shoulders']::text[], array['body only']::text[], 'core', 'intermediate', 'Podpór na rękach z kolanami przy klatce. Regresja L-situ.', 'isolation', 'static', array[]::text[], null, 'wger', '9396a728-3da4-4390-ae4d-882395805008', 'wger.de, autor: clafal, licencja CC-BY-SA 4', null) on conflict (source, external_id) do nothing;
insert into public.exercises (name_pl, name_en, muscle_groups, primary_muscles, secondary_muscles, equipment, movement_pattern, level, description, mechanic, force, image_urls, image_url, source, external_id, attribution, created_by) values ('Stanie na rękach w pozycji żabki', 'Frog Stand', array['shoulders','triceps','abdominals','forearms']::text[], array['shoulders']::text[], array['triceps','abdominals','forearms']::text[], array['body only']::text[], 'other', 'intermediate', 'Balans na dłoniach z kolanami opartymi o łokcie. Wprowadzenie do balansów na rękach.', 'isolation', 'static', array[]::text[], null, 'wger', '00eae665-ff78-4373-9c43-f44a4a1b43e0', 'wger.de, autor: clafal, licencja CC-BY-SA 4', null) on conflict (source, external_id) do nothing;
insert into public.exercises (name_pl, name_en, muscle_groups, primary_muscles, secondary_muscles, equipment, movement_pattern, level, description, mechanic, force, image_urls, image_url, source, external_id, attribution, created_by) values ('Samolot biodrowy', 'Hip Airplane', array['glutes','hamstrings','abductors']::text[], array['glutes']::text[], array['hamstrings','abductors']::text[], array['body only']::text[], 'hinge', 'intermediate', 'W pochyleniu na jednej nodze powolne otwieranie i zamykanie miednicy w rotacji. Kontrola biodra i równowaga.', 'isolation', 'static', array[]::text[], null, 'wger', '553fb643-32f0-447f-aecb-cdf75398d742', 'wger.de, autor: TobiasFalk, licencja CC-BY-SA 4', null) on conflict (source, external_id) do nothing;
insert into public.exercises (name_pl, name_en, muscle_groups, primary_muscles, secondary_muscles, equipment, movement_pattern, level, description, mechanic, force, image_urls, image_url, source, external_id, attribution, created_by) values ('Unoszenia Y-T-W', 'YTW Raises', array['middle back','shoulders','traps']::text[], array['middle back']::text[], array['shoulders','traps']::text[], array['body only']::text[], 'pull_h', 'beginner', 'Leżąc przodem unoszenie rąk kolejno w kształt liter Y, T i W z ściąganiem łopatek. Zdrowie barków i postawa.', 'isolation', 'pull', array[]::text[], null, 'wger', '142fcef5-63a7-4d30-81e4-bc9d7073fe99', 'wger.de, autor: probablyforging, licencja CC-BY-SA 4', null) on conflict (source, external_id) do nothing;
insert into public.exercises (name_pl, name_en, muscle_groups, primary_muscles, secondary_muscles, equipment, movement_pattern, level, description, mechanic, force, image_urls, image_url, source, external_id, attribution, created_by) values ('Negatywy podciągania', 'Negative Pull-Up', array['lats','biceps','middle back']::text[], array['lats']::text[], array['biceps','middle back']::text[], array['body only']::text[], 'pull_v', 'beginner', 'Wskoczenie do górnej pozycji podciągnięcia i bardzo powolne opuszczanie (3–5 s). Najlepsza droga do pierwszego podciągnięcia.', 'compound', 'pull', array[]::text[], null, 'wger', '939a8f83-efad-4556-9773-7b9410c08b3f', 'wger.de, autor: lightking, licencja CC-BY-SA 4', null) on conflict (source, external_id) do nothing;
insert into public.exercises (name_pl, name_en, muscle_groups, primary_muscles, secondary_muscles, equipment, movement_pattern, level, description, mechanic, force, image_urls, image_url, source, external_id, attribution, created_by) values ('Utrzymanie w podciągnięciu', 'Pull-Up Isometric Hold', array['lats','biceps','forearms']::text[], array['lats']::text[], array['biceps','forearms']::text[], array['body only']::text[], 'pull_v', 'beginner', 'Utrzymanie brody nad drążkiem tak długo, jak się da. Buduje siłę w najtrudniejszym punkcie podciągania.', 'compound', 'static', array[]::text[], null, 'wger', '5e3a322b-98dd-4197-b16f-4ac72c42c223', 'wger.de, autor: DiscoCop, licencja CC-BY-SA 4', null) on conflict (source, external_id) do nothing;
insert into public.exercises (name_pl, name_en, muscle_groups, primary_muscles, secondary_muscles, equipment, movement_pattern, level, description, mechanic, force, image_urls, image_url, source, external_id, attribution, created_by) values ('Podciąganie z wyskoku', 'Jumping Pull-Up', array['lats','biceps','quadriceps']::text[], array['lats']::text[], array['biceps','quadriceps']::text[], array['body only']::text[], 'pull_v', 'beginner', 'Podciągnięcie wspomagane wyskokiem z podłogi lub skrzyni. Regresja dla osób, które jeszcze nie podciągają się samodzielnie.', 'compound', 'pull', array[]::text[], null, 'wger', '8b60bc5c-ced8-4e49-9b0e-a581d51fc66a', 'wger.de, autor: lightking, licencja CC-BY-SA 4', null) on conflict (source, external_id) do nothing;
insert into public.exercises (name_pl, name_en, muscle_groups, primary_muscles, secondary_muscles, equipment, movement_pattern, level, description, mechanic, force, image_urls, image_url, source, external_id, attribution, created_by) values ('Martwy ciąg rumuński na jednej nodze bez obciążenia', 'Single-Leg Romanian Deadlift', array['hamstrings','glutes','lower back']::text[], array['hamstrings']::text[], array['glutes','lower back']::text[], array['body only']::text[], 'hinge', 'beginner', 'Skłon na jednej nodze z wolną nogą w linii z tułowiem. Nauka wzorca i równowagi przed wersją z ciężarem.', 'compound', 'pull', array[]::text[], null, 'wger', '957ca37c-b6d7-4c30-8ba9-9512b0fa2659', 'wger.de, autor: admin, licencja CC-BY-SA 4', null) on conflict (source, external_id) do nothing;
insert into public.exercises (name_pl, name_en, muscle_groups, primary_muscles, secondary_muscles, equipment, movement_pattern, level, description, mechanic, force, image_urls, image_url, source, external_id, attribution, created_by) values ('Hip thrust na jednej nodze z hantlem', 'Dumbbell Single-Leg Hip Thrust', array['glutes','hamstrings']::text[], array['glutes']::text[], array['hamstrings']::text[], array['dumbbell']::text[], 'hinge', 'intermediate', 'Hip thrust z jedną nogą w powietrzu i hantlem na biodrze pracującej strony. Wyrównuje różnice między stronami.', 'isolation', 'push', array[]::text[], null, 'wger', '7cc24acf-3fc9-4d14-a461-cd00d1d18f0e', 'wger.de, autor: carlos3c, licencja CC-BY-SA 4', null) on conflict (source, external_id) do nothing;
insert into public.exercises (name_pl, name_en, muscle_groups, primary_muscles, secondary_muscles, equipment, movement_pattern, level, description, mechanic, force, image_urls, image_url, source, external_id, attribution, created_by) values ('Przysiad z wyciśnięciem sztangi w uchwycie (landmine)', 'Landmine Squat to Press', array['quadriceps','shoulders','glutes','triceps']::text[], array['quadriceps']::text[], array['shoulders','glutes','triceps']::text[], array['barbell']::text[], 'squat', 'intermediate', 'Koniec sztangi zaczepionej w rogu trzymany przy klatce, przysiad i wyciśnięcie w górę i w przód. Przyjazne dla barków.', 'compound', 'push', array[]::text[], null, 'wger', '67bca611-d9f1-4855-9e02-ecc8d7d688e9', 'wger.de, autor: beagle, licencja CC-BY-SA 4', null) on conflict (source, external_id) do nothing;
insert into public.exercises (name_pl, name_en, muscle_groups, primary_muscles, secondary_muscles, equipment, movement_pattern, level, description, mechanic, force, image_urls, image_url, source, external_id, attribution, created_by) values ('Rotacje ze sztangą w uchwycie (landmine)', 'Landmine Rotation', array['abdominals','shoulders','glutes']::text[], array['abdominals']::text[], array['shoulders','glutes']::text[], array['barbell']::text[], 'rotation', 'intermediate', 'Prowadzenie końca sztangi łukiem z jednego biodra na drugie z obrotem z bioder, ręce proste. Moc rotacyjna.', 'compound', 'pull', array[]::text[], null, 'wger', '73c1e130-fba9-473b-a093-a5712e2ae34d', 'wger.de, autor: aboksz, licencja CC-BY-SA 4', null) on conflict (source, external_id) do nothing;
