insert into public.exercise_relations (from_exercise, to_exercise, kind) select (select id from public.exercises where name_en = 'Dumbbell Sumo Deadlift' and source <> 'own' order by source = 'free-exercise-db' desc limit 1), (select id from public.exercises where name_en = 'Kettlebell Deadlift' and source <> 'own' order by source = 'free-exercise-db' desc limit 1), 'alternative' where (select id from public.exercises where name_en = 'Dumbbell Sumo Deadlift' and source <> 'own' order by source = 'free-exercise-db' desc limit 1) is not null and (select id from public.exercises where name_en = 'Kettlebell Deadlift' and source <> 'own' order by source = 'free-exercise-db' desc limit 1) is not null on conflict do nothing;
